import sys; sys.path.insert(0,"/tmp")
from harness import Entr
import os, time

def trial(op):
    os.makedirs("/tmp/t8",exist_ok=True)
    for f in os.listdir("/tmp/t8"):
        p=os.path.join("/tmp/t8",f)
        if os.path.isfile(p): os.unlink(p)
    open("/tmp/t8/a.txt","w").write("hello")
    e=Entr(["-n","echo","RUN"], ["/tmp/t8/a.txt"], env={"EV_TRACE":"1"})
    e.read_and_print("init",0.5)
    t0=time.time()
    if op=="rename": os.rename("/tmp/t8/a.txt","/tmp/t8/b.txt")
    elif op=="delete": os.unlink("/tmp/t8/a.txt")
    elif op=="move_out": os.rename("/tmp/t8/a.txt","/tmp/t8_b.txt")
    # poll frequently
    while time.time()-t0<4:
        e.poll_read(0.1)
        if e.out or e.err or e.p.poll() is not None:
            o,er=e.snapshot()
            print(f"{op} t={time.time()-t0:.3f} rc={e.p.poll()} out={o!r} err={er!r}")
            if e.p.poll() is not None: break
    e.kill()

for op in ["rename","delete","move_out"]:
    trial(op)
PY"}

