static void *
xmalloc(size_t n)
{
    void *p = malloc(n ? n : 1);
    if (p == NULL)
        err(1, "malloc");
    return p;
}

static void *
xrealloc(void *p, size_t n)
{
    void *q = realloc(p, n ? n : 1);
    if (q == NULL)
        err(1, "realloc");
    return q;
}

static char *
xstrdup(const char *s)
{
    char *p = strdup(s);
    if (p == NULL)
        err(1, "strdup");
    return p;
}

static int
encode_wait_status(int st)
{
    if (WIFEXITED(st))
        return WEXITSTATUS(st);
    if (WIFSIGNALED(st))
        return 128 + WTERMSIG(st);
    return 1;
}

static void
cleanup_tty(void)
{
    if (tty_is_setup && tty_fd >= 0)
        (void)tcsetattr(tty_fd, TCSANOW, &tty_saved);
