/*
 * POSIX basename() for the one name displayed in exit-status lines.
 * It deliberately updates the supplied buffer like the XPG function
 * that the reference behaviour exposes: trailing slashes on a utility
 * name are removed before the utility is executed.  A name consisting
 * solely of slashes is left alone.
 */
static char *
basename_mutating(char *s)
{
    char *p;
    int all_slashes = 1;

    if (s == NULL || *s == '\0')
        return (char *)".";
    for (p = s; *p != '\0'; p++) {
        if (*p != '/') {
            all_slashes = 0;
            break;
        }
    }
    if (all_slashes)
        return s + strlen(s) - 1;

    p = s + strlen(s) - 1;
    while (p > s && *p == '/')
        *p-- = '\0';
    p = strrchr(s, '/');
    return p ? p + 1 : s;
}

static char *
dirname_dup(const char *path)
{
    const char *slash = strrchr(path, '/');
    const char *end;
    char *out;
    size_t n;

    if (slash == NULL)
        return xstrdup(".");
    if (slash == path)
        return xstrdup("/");
    end = slash;
    while (end > path && end[-1] == '/')
        end--;
    if (end == path)
        return xstrdup("/");
    n = (size_t)(end - path);
    out = xmalloc(n + 1);
    memcpy(out, path, n);
    out[n] = '\0';
    return out;
}

