    rec->watch_is_special_symlink = special;
    rec->has_watch_identity = 1;
    rec->watch_dev = identity.st_dev;
    rec->watch_ino = identity.st_ino;
    wd_map_ensure(wd);
    if (wd_map[wd] == 0)
