        }

        r = try_register_record(rec_idx, 1, &saved_errno);
        if (r == REG_OK)
            return 0;
        if (r == REG_ADD_FAILED)
            fatal_failed_register(saved_errno);

        cannot_open_errno = saved_errno;
        if (monotonic_ms() >= deadline) {
            cannot_open_set = 1;
            cannot_open_record = rec_idx;
            return 1;
        }
        sleep_ms(10);
    }
}

/* ------------------------------------------------------------------ */
/* Reading and converting inotify events                               */
/* ------------------------------------------------------------------ */

static unsigned
map_inotify_mask(uint32_t mask, int special_symlink)
{
    unsigned flags = 0;

    (void)special_symlink;
    if (mask & IN_ATTRIB)
        flags |= NOTE_ATTRIB;
    if (mask & (IN_CLOSE_WRITE | IN_MODIFY | IN_CREATE | IN_DELETE))
        flags |= NOTE_WRITE;
    if (mask & IN_DELETE_SELF)
        flags |= NOTE_DELETE;
    if (mask & (IN_MOVE_SELF | IN_MOVED_FROM | IN_MOVED_TO))
        flags |= NOTE_RENAME;
    return flags;
}

static Event *
read_and_convert_events(int *out_len)
{
    RawEvent *raw = NULL;
    size_t raw_len = 0, raw_cap = 0;
    Event *events = NULL;
    size_t events_len = 0, events_cap = 0;
    size_t i;

    *out_len = 0;
    conversion_aborted = 0;

    /* Start with any events preserved while removing a watch. */
    if (pending_raw_len > 0) {
        raw = pending_raw;
        raw_len = pending_raw_len;
        raw_cap = pending_raw_cap;
        pending_raw = NULL;
        pending_raw_len = pending_raw_cap = 0;
    }

    for (;;) {
        char buf[65536];
        ssize_t n = read(inotify_fd, buf, sizeof(buf));
        size_t off;

        if (n < 0) {
            if (errno == EINTR)
                continue;
            break;              /* EAGAIN in the usual case */
        }
        if (n == 0)
            break;
        off = 0;
        while (off + sizeof(struct inotify_event) <= (size_t)n) {
            struct inotify_event *ev =
                (struct inotify_event *)(buf + off);
            if (raw_len == raw_cap) {
                raw_cap = raw_cap ? raw_cap * 2 : 128;
                raw = xrealloc(raw, raw_cap * sizeof(*raw));
            }
            raw[raw_len].wd = ev->wd;
            raw[raw_len].mask = ev->mask;
            raw_len++;
            off += sizeof(struct inotify_event) + ev->len;
        }
    }

    /* Group by watch descriptor, preserving first-seen order. */
    for (i = 0; i < raw_len; i++) {
        int rec_idx;
        size_t j;
        Event *e = NULL;

        if (raw[i].wd < 0)
            continue;           /* IN_Q_OVERFLOW */
        rec_idx = wd_map_get(raw[i].wd);
        if (rec_idx < 0)
            continue;

        for (j = 0; j < events_len; j++) {
            if (events[j].wd == raw[i].wd) {
                e = &events[j];
                break;
            }
        }
        if (e == NULL) {
            if (events_len == events_cap) {
                events_cap = events_cap ? events_cap * 2 : 32;
                events = xrealloc(events,
                    events_cap * sizeof(*events));
            }
            e = &events[events_len++];
            memset(e, 0, sizeof(*e));
            e->rec = rec_idx;
            e->wd = raw[i].wd;
        }
        e->raw_mask |= raw[i].mask;
        e->fflags |= map_inotify_mask(raw[i].mask,
            records[rec_idx].watch_is_special_symlink);
        if (raw[i].mask & (IN_DELETE_SELF | IN_MOVE_SELF | IN_IGNORED))
            e->self_changed = 1;
        if (raw[i].mask & (IN_DELETE_SELF | IN_IGNORED))
            e->watch_removed = 1;
    }
    free(raw);

    for (i = 0; i < events_len; i++) {
        if (events[i].fflags == 0 && events[i].watch_removed)
            events[i].silent = 1;
    }

    /* Re-register self-deleted/self-moved watches. */
    for (i = 0; i < events_len; i++) {
        Event *e = &events[i];
        FileRecord *rec;

        if (!e->self_changed)
            continue;
        rec = &records[e->rec];

        if (rec->is_dir) {
            if (e->watch_removed) {
                int saved_errno = 0;
                clear_watch(e->rec, 0);
                (void)try_register_record(e->rec, 0, &saved_errno);
            } else if (!same_watch_identity(e->rec)) {
                int saved_errno = 0;
                clear_watch(e->rec, 1);
                (void)try_register_record(e->rec, 0, &saved_errno);
            }
            continue;
        }

        if (!e->watch_removed && same_watch_identity(e->rec))
            continue;

        clear_watch(e->rec, !e->watch_removed);
        {
            int rr = reopen_record(e->rec);
            if (rr == 1)
                break;          /* graceful cannot-open */
            if (rr == 2) {
                conversion_aborted = 1;
                break;
            }
        }
    }

    *out_len = (int)events_len;
    return events;
}

/* poll() wrapper; returns 1=inotify, 2=tty, 4=interrupted. */
static int
poll_activity(int timeout_ms)
{
    struct pollfd pfds[2];
    int nfds = 0;
    int inotify_index = -1, tty_index = -1;
    int r, result = 0;

    if (inotify_fd >= 0) {
        inotify_index = nfds;
        pfds[nfds].fd = inotify_fd;
        pfds[nfds].events = POLLIN;
        pfds[nfds].revents = 0;
        nfds++;
    }
    if (tty_is_setup && tty_fd >= 0) {
        tty_index = nfds;
        pfds[nfds].fd = tty_fd;
        pfds[nfds].events = POLLIN;
        pfds[nfds].revents = 0;
        nfds++;
    }
    if (nfds == 0) {
        sleep_ms(timeout_ms < 0 ? 100 : timeout_ms);
        return (terminating_signal || child_signal_seen) ? 4 : 0;
    }

    r = poll(pfds, (nfds_t)nfds, timeout_ms);
    if (r < 0) {
        if (errno == EINTR)
            return 4;
        return 0;
    }
    if (r == 0)
        return 0;
    if (inotify_index >= 0 && pfds[inotify_index].revents != 0)
        result |= 1;
    if (tty_index >= 0 && pfds[tty_index].revents != 0)
        result |= 2;
    return result;
}

static void
merge_event_into(Event *dst, const Event *src)
{
    dst->fflags |= src->fflags;
    dst->raw_mask |= src->raw_mask;
    dst->self_changed |= src->self_changed;
    dst->watch_removed |= src->watch_removed;
    if (!src->silent)
        dst->silent = 0;
}

static Event *
collate_events(Event *events, int *nev_io)
{
    int nev = *nev_io;

    while (nev < MAX_EVENTS && !cannot_open_set &&
           !conversion_aborted && !terminating_signal && !status_dead) {
        int act = poll_activity(50);
        Event *more;
        int more_nev = 0;
        int i;

        if (act == 0)
            break;
        if (act & 4)
            break;
        if (act & 2)
            break;              /* leave keyboard for the main loop */
        if (!(act & 1))
            break;

        more = read_and_convert_events(&more_nev);
        for (i = 0; i < more_nev; i++) {
            if (nev > 0 && events[nev - 1].rec == more[i].rec) {
                merge_event_into(&events[nev - 1], &more[i]);
            } else if (nev < MAX_EVENTS) {
                events = xrealloc(events,
                    (size_t)(nev + 1) * sizeof(*events));
                events[nev++] = more[i];
            }
        }
        free(more);
    }
    *nev_io = nev;
    return events;
}

static void
drain_events(void)
{
    while (!cannot_open_set && !conversion_aborted &&
           !terminating_signal && !status_dead) {
        int act = poll_activity(50);
        Event *ev;
        int nev = 0;

        if (act == 0)
            break;
        if (act & (2 | 4))
            break;
        if (!(act & 1))
            break;
        ev = read_and_convert_events(&nev);
        free(ev);
    }
}

/* ------------------------------------------------------------------ */
/* Status (awk) process                                                */
/* ------------------------------------------------------------------ */

static const char status_script_text[] =
    "# http://eradman.com/entrproject/status-filters.html\n"
    "/^signal/ { print $3, \"terminated by signal\", $2; }\n"
    "/^exit/ { print $3, \"returned exit code\", $2; }\n";

static void
start_status_process(void)
{
    const char *env_path;
    char *script_path;
    struct stat sb;
    int pipe_fds[2];
    pid_t pid;

    env_path = getenv("ENTR_STATUS_SCRIPT");
    if (env_path != NULL && env_path[0] != '\0') {
        script_path = xstrdup(env_path);
    } else {
        struct passwd *pw = getpwuid(getuid());
        const char *home = pw ? pw->pw_dir : getenv("HOME");
        if (home == NULL)
            home = "";
        if (asprintf(&script_path, "%s/.entr/status.awk", home) < 0)
            err(1, "asprintf");
    }

    if (stat(script_path, &sb) != 0) {
        char *dir_copy = xstrdup(script_path);
        char *parent = dirname_dup(script_path);
        int fd;

        printf("entr: created '%s'\n", script_path);
        (void)mkdir(parent, 0750);
        free(parent);
        free(dir_copy);

        fd = open(script_path, O_WRONLY | O_CREAT | O_TRUNC, 0640);
        if (fd < 0)
            err(1, "open");
        (void)!write(fd, status_script_text,
            strlen(status_script_text));
        close(fd);
    }

    if (pipe2(pipe_fds, O_CLOEXEC) != 0)
        err(1, "pipe");
    pid = fork();
    if (pid < 0)
        err(1, "fork");
    if (pid == 0) {
        char *awk_argv[7];
        int ai = 0;

        if (dup2(pipe_fds[0], STDIN_FILENO) < 0)
            _exit(127);
        close(pipe_fds[0]);
        close(pipe_fds[1]);

        awk_argv[ai++] = (char *)"awk";
        awk_argv[ai++] = (char *)"-F";
        awk_argv[ai++] = (char *)"|";
        awk_argv[ai++] = (char *)"-f";
        awk_argv[ai++] = script_path;
        if (opt_status == 1)
            awk_argv[ai++] = (char *)"-S";
        awk_argv[ai] = NULL;
        execvp("awk", awk_argv);
        err(1, "could not exec /usr/bin/awk");
    }
    close(pipe_fds[0]);
    status_fd = pipe_fds[1];
    status_pid = pid;
    free(script_path);
}

static void
report_child_status(int wait_st)
{
    if (!opt_status || status_dead || status_fd < 0)
        return;
    if (WIFEXITED(wait_st)) {
        (void)!dprintf(status_fd, "exit|%d|%s\n",
            WEXITSTATUS(wait_st), utility_status_name);
    } else if (WIFSIGNALED(wait_st)) {
        (void)!dprintf(status_fd, "signal|%d|%s\n",
            WTERMSIG(wait_st), utility_status_name);
    }
}

/* ------------------------------------------------------------------ */
/* Running the utility                                                 */
/* ------------------------------------------------------------------ */

static pid_t
spawn_utility(void)
{
    pid_t pid;
    char *shell_argv[5];
    char **exec_argv;
    const char *trigger_path = "";

    if (trigger_record >= 0)
        trigger_path = records[trigger_record].path;

    if (opt_shell) {
        shell_argv[0] = shell_path;
        shell_argv[1] = (char *)"-c";
        shell_argv[2] = shell_command;
        shell_argv[3] = (char *)trigger_path;
        shell_argv[4] = NULL;
        exec_argv = shell_argv;
    } else {
        if (underscore_index >= 0)
            utility_argv[underscore_index] = (char *)trigger_path;
        exec_argv = utility_argv;
    }

    fflush(stdout);
    if (opt_clear == 1)
        (void)!write(STDOUT_FILENO, "\033[2J\033[H", 7);
    else if (opt_clear >= 2)
        (void)!write(STDOUT_FILENO, "\033[2J\033[3J\033[H", 11);

    if (tty_is_setup && !opt_restart)
        (void)tcsetattr(tty_fd, TCSANOW, &tty_saved);

    pid = fork();
    if (pid < 0)
        err(1, "fork");

    if (pid == 0) {
        if (opt_restart) {
            int nullfd;
            (void)setpgid(0, 0);
            nullfd = open("/dev/null", O_RDONLY);
            if (nullfd >= 0) {
                (void)dup2(nullfd, STDIN_FILENO);
                if (nullfd > STDERR_FILENO)
                    close(nullfd);
            }
        } else if (tty_is_setup) {
            (void)dup2(tty_fd, STDIN_FILENO);
        }
        execvp(exec_argv[0], exec_argv);
        err(1, "exec %s", exec_argv[0]);
    }

    if (opt_restart) {
        (void)setpgid(pid, pid);
        restart_child_pid = pid;
        restart_child_exited = 0;
    }
    return pid;
}

static void
wait_for_sync_utility(pid_t utility_pid)
{
    int final_status = 0;
    int have_final = 0;

    for (;;) {
        int st;
        pid_t w = waitpid(-1, &st, 0);

        if (w < 0) {
            if (errno == EINTR)
                continue;
            break;
        }
        if (w == status_pid && status_pid != 0) {
            note_child_exit(w, st);
            continue;
        }
        if (w == utility_pid) {
            final_status = st;
            have_final = 1;
            break;
        }
        /* Any other direct child is not expected here. */
        note_child_exit(w, st);
    }

    if (have_final) {
        last_child_wait_status = final_status;
        last_child_status = encode_wait_status(final_status);
        report_child_status(final_status);
    }
    if (tty_is_setup)
        (void)tcsetattr(tty_fd, TCSANOW, &tty_watch);
}

static void
do_sync_run(void)
{
    pid_t pid = spawn_utility();
    wait_for_sync_utility(pid);
}

static void
terminate_restart_child(void)
{
    pid_t target;
    int st;

    if (!opt_restart || restart_child_pid <= 0)
        return;
    target = restart_child_pid;
    if (kill(-target, restart_signal_no) != 0)
        (void)kill(target, restart_signal_no);

    for (;;) {
        pid_t w = waitpid(-1, &st, 0);
        if (w < 0) {
            if (errno == EINTR)
                continue;
            restart_child_pid = 0;
            break;
        }
        if (w == target) {
            restart_child_pid = 0;
            last_child_wait_status = st;
            last_child_status = encode_wait_status(st);
            break;
        }
        note_child_exit(w, st);
    }
}

/* ------------------------------------------------------------------ */
/* Termination paths                                                   */
/* ------------------------------------------------------------------ */

static void
finalize_signal(void)
{
    int sig = terminating_signal;

    if (opt_restart)
        terminate_restart_child();
    cleanup_tty();
    if (sig == SIGTERM) {
        struct sigaction sa;
        sigset_t set;

        memset(&sa, 0, sizeof(sa));
        sa.sa_handler = SIG_DFL;
        sigemptyset(&sa.sa_mask);
        sigaction(SIGTERM, &sa, NULL);
        sigemptyset(&set);
        sigaddset(&set, SIGTERM);
        sigprocmask(SIG_UNBLOCK, &set, NULL);
        raise(SIGTERM);
        _exit(128 + SIGTERM);
    }
    _exit(0);
}

static void
finalize_status_dead(void)
{
    cleanup_tty();
    _exit(0);
}

static void
finalize_quit(void)
{
    if (opt_restart)
        terminate_restart_child();
    cleanup_tty();
    _exit(0);
}

static void
finalize_dir_altered(void)
{
    if (opt_restart)
        terminate_restart_child();
    warnx("directory altered");
    cleanup_tty();
    exit(2);
}

static void
finalize_cannot_open(void)
{
    const char *path = "?";

    if (cannot_open_record >= 0)
        path = records[cannot_open_record].path;
    errno = cannot_open_errno;
    warn("cannot open '%s'", path);
    if (opt_restart)
        terminate_restart_child();
    cleanup_tty();
    exit(1);
}

static void
finalize_z_exit(void)
{
    cleanup_tty();
    exit(last_child_status);
}

static void
after_sync_run(void)
{
    if (terminating_signal)
        finalize_signal();
    if (status_dead)
        finalize_status_dead();
    if (pending_dir_altered)
        finalize_dir_altered();
    if (opt_exit_after)
        finalize_z_exit();
    if (!opt_aggressive) {
        drain_events();
        if (cannot_open_set)
            finalize_cannot_open();
        if (conversion_aborted && child_signal_seen)
            reap_children_nonblocking();
        if (child_signal_seen)
            reap_children_nonblocking();
        if (terminating_signal)
            finalize_signal();
        if (status_dead)
            finalize_status_dead();
    }
}

/* ------------------------------------------------------------------ */
/* Processing file events                                              */
/* ------------------------------------------------------------------ */

static int
stat_for_baseline(int rec_idx, struct stat *sb)
{
    FileRecord *rec = &records[rec_idx];

    if (follow_symlink)
        return stat(rec->path, sb);
    return lstat(rec->path, sb);
}

static void
process_events(Event *events, int nev, int *run_needed, int *dir_altered)
{
    int i;
    int first_trigger = -1;

    *run_needed = 0;
    *dir_altered = 0;

    for (i = 0; i < nev; i++) {
        Event *e = &events[i];
        FileRecord *rec = &records[e->rec];

        if (rec->is_dir) {
            int new_count = count_dir_entries(rec->path);

            if (new_count != rec->dir_count) {
                rec->dir_count = new_count;
                *dir_altered = 1;
                *run_needed = 1;
                if (ev_trace && !opt_restart &&
                    !(e->fflags & NOTE_ATTRIB)) {
                    fprintf(stderr, "%d/%d: fflags: 0x%x %c %o %s\n",
                        i, nev, e->fflags, 'd',
                        (unsigned)rec->mode, rec->path);
                }
            }
            continue;
        }

        if (e->silent) {
            *run_needed = 1;
            continue;
        }

        {
            int qualifies = 0;
            mode_t trace_mode = rec->mode;
            struct stat sb;

            if (e->fflags & (NOTE_DELETE | NOTE_RENAME)) {
                if (stat_for_baseline(e->rec, &sb) == 0) {
                    rec->mode = sb.st_mode;
                    trace_mode = sb.st_mode;
                }
                qualifies = 1;
            }
            if (e->fflags & NOTE_ATTRIB) {
                if (stat_for_baseline(e->rec, &sb) == 0) {
                    if (sb.st_mode != rec->mode)
                        qualifies = 1;
                    rec->mode = sb.st_mode;
                    trace_mode = sb.st_mode;
                }
            }
            if (e->fflags & (NOTE_WRITE | NOTE_EXTEND))
                qualifies = 1;

            if (ev_trace) {
                fprintf(stderr, "%d/%d: fflags: 0x%x %c %o %s\n",
                    i, nev, e->fflags, 'r',
                    (unsigned)trace_mode, rec->path);
            }
            if (qualifies) {
                *run_needed = 1;
                if (first_trigger < 0)
                    first_trigger = e->rec;
            }
        }
    }

    if (first_trigger >= 0)
        trigger_record = first_trigger;
}

/* ------------------------------------------------------------------ */
/* Input (file names)                                                  */
/* ------------------------------------------------------------------ */

static unsigned char stdin_raw[4096];
static size_t stdin_raw_pos;
static size_t stdin_raw_len;
static int stdin_saw_eof;
static int stdin_saw_error;

/* Return 1=chunk, 0=EOF/error, -1=interrupted by a fatal signal. */
static int
read_stdin_chunk(char out[PATH_BUF])
{
    size_t out_len = 0;

    while (out_len < PATH_BUF - 1) {
        unsigned char c;

        if (stdin_raw_pos >= stdin_raw_len) {
            ssize_t n;

            if (stdin_saw_eof || stdin_saw_error)
                break;
            if (terminating_signal)
                return -1;
            if (child_signal_seen) {
                reap_children_nonblocking();
                if (status_dead || terminating_signal)
                    return -1;
            }

            {
                struct pollfd pfd;
                int pr;

                pfd.fd = STDIN_FILENO;
                pfd.events = POLLIN;
                pfd.revents = 0;
                pr = poll(&pfd, 1, 100);
                if (pr < 0 && errno == EINTR)
                    continue;
                if (pr == 0)
                    continue;
                if (pr < 0) {
                    stdin_saw_error = 1;
                    break;
                }
            }
            n = read(STDIN_FILENO, stdin_raw, sizeof(stdin_raw));
            if (n < 0) {
                if (errno == EINTR || errno == EAGAIN)
                    continue;
                stdin_saw_error = 1;
                break;
            }
            if (n == 0) {
                stdin_saw_eof = 1;
                break;
            }
            stdin_raw_pos = 0;
            stdin_raw_len = (size_t)n;
        }

        c = stdin_raw[stdin_raw_pos++];
        out[out_len++] = (char)c;
        if (c == '\n')
            break;
    }
    out[out_len] = '\0';
    return out_len > 0 ? 1 : 0;
}

static int
add_record(const char *path, int is_dir, int is_symlink, int synthetic_parent,
    mode_t mode, int dir_count)
{
    FileRecord *rec;
    int idx;

    if (records_len == records_cap) {
        records_cap = records_cap ? records_cap * 2 : 32;
        records = xrealloc(records, records_cap * sizeof(*records));
    }
    idx = (int)records_len++;
    rec = &records[idx];
    memset(rec, 0, sizeof(*rec));
    rec->path = xstrdup(path);
    rec->is_dir = is_dir;
    rec->is_symlink_input = is_symlink;
    rec->synthetic_parent = synthetic_parent;
    rec->mode = mode;
    rec->dir_count = dir_count;
    rec->wd = -1;
    return idx;
}

static void
maybe_add_parent_dir(int rec_idx)
{
    char *parent;
    struct stat sb;
    struct stat ls;
    size_t i;
    int count;

    parent = dirname_dup(records[rec_idx].path);
    for (i = 0; i < records_len; i++) {
        if (strcmp(records[i].path, parent) == 0) {
            free(parent);
            return;
        }
    }
    if (stat(parent, &sb) != 0) {
        warnx("unable to stat '%s'", parent);
        free(parent);
        return;
    }
    count = count_dir_entries(parent);
    (void)lstat(parent, &ls);
    add_record(parent, 1,
        S_ISLNK(ls.st_mode), 1, sb.st_mode, count);
    free(parent);
}

/* Return 0 normally, 1 if reading was interrupted by a signal. */
static int
process_input(int *accepted_count)
{
    char buf[PATH_BUF];
    int accepted = 0;

    for (;;) {
        int rr = read_stdin_chunk(buf);
        char *nl;
        struct stat class_sb, link_sb;
        int have_link;
        int is_dir, is_link, is_reg;
        int idx;

        if (rr < 0)
            return 1;
        if (rr == 0)
            break;

        nl = strchr(buf, '\n');
        if (nl != NULL)
            *nl = '\0';
        if (buf[0] == '\0')
            continue;

        have_link = lstat(buf, &link_sb) == 0;
        if (follow_symlink) {
            if (stat(buf, &class_sb) != 0) {
                warnx("unable to stat '%s'", buf);
                continue;
            }
        } else {
            if (!have_link) {
                warnx("unable to stat '%s'", buf);
                continue;
            }
            class_sb = link_sb;
        }

        is_reg = S_ISREG(class_sb.st_mode);
        is_dir = S_ISDIR(class_sb.st_mode);
        is_link = S_ISLNK(class_sb.st_mode);
        if (!is_reg && !is_dir && !is_link)
            continue;

        idx = add_record(buf, is_dir,
            have_link && S_ISLNK(link_sb.st_mode), 0,
            class_sb.st_mode, 0);
        if (is_dir)
            records[idx].dir_count = count_dir_entries(buf);

        if (accepted == 0)
            trigger_record = idx;
        accepted++;

        if (opt_dirwatch > 0 && !is_dir)
            maybe_add_parent_dir(idx);

        if (terminating_signal)
            return 1;
    }

    *accepted_count = accepted;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Keyboard                                                            */
/* ------------------------------------------------------------------ */

#define TTYCMD_EOF (-2)

static int
read_tty_command(void)
{
    unsigned char c;
    ssize_t n = read(tty_fd, &c, 1);

    if (n == 1)
        return c;
    if (n < 0 && (errno == EINTR || errno == EAGAIN))
        return 0;
    return TTYCMD_EOF;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int
main(int argc, char **argv)
{
    int ch;
    int accepted_count = 0;
    int input_interrupted;
    size_t i;
    int initial_pending;

    if (argc > 1 && strcmp(argv[1], "-h") == 0)
        usage(1);

    while ((ch = getopt(argc, argv, "+acdnprsxz")) != -1) {
        switch (ch) {
        case 'a': opt_aggressive = 1; break;
        case 'c': opt_clear++; break;
        case 'd': opt_dirwatch++; break;
        case 'n': opt_noninteractive = 1; break;
        case 'p': opt_postpone = 1; break;
        case 'r': opt_restart = 1; break;
        case 's': opt_shell = 1; break;
        case 'x': opt_status++; break;
        case 'z': opt_exit_after = 1; break;
        default: usage(0);
        }
    }
    if (optind >= argc)
        usage(0);

    utility_argv = argv + optind;
    utility_argc = argc - optind;

    if (opt_restart && opt_status)
        errx(1, "-r and -x may not be combined");
    if (opt_shell && utility_argc > 1)
        errx(1, "-s requires commands to be formatted as a single argument");

    if (opt_shell) {
        const char *sh = getenv("SHELL");
        shell_path = xstrdup(sh ? sh : "/bin/sh");
        shell_command = utility_argv[0];
        utility_status_name = basename_mutating(shell_path);
    } else {
        int j;
        for (j = 0; j < utility_argc; j++) {
            if (strcmp(utility_argv[j], "/_") == 0) {
                underscore_index = j;
                break;
            }
        }
        utility_status_name = basename_mutating(utility_argv[0]);
    }

    {
        const char *sig = getenv("ENTR_RESTART_SIGNAL");
        if (sig != NULL) {
            const char *name = sig;
            if (strncmp(name, "SIG", 3) == 0)
                name += 3;
            if (strcmp(name, "HUP") == 0)
                restart_signal_no = SIGHUP;
            else if (strcmp(name, "INT") == 0)
                restart_signal_no = SIGINT;
            else if (strcmp(name, "QUIT") == 0)
                restart_signal_no = SIGQUIT;
            else
                errx(1,
                    "unrecognized signal: %s <> (HUP, INT, QUIT, TERM, USR1, USR2)",
                    name);
        }
    }

    if (getenv("PAGER") == NULL)
        (void)setenv("PAGER", "/bin/cat", 1);

    ev_trace = getenv("EV_TRACE") != NULL;
    inotify_workaround = getenv("ENTR_INOTIFY_WORKAROUND") != NULL;
    follow_symlink = getenv("ENTR_FOLLOW_SYMLINK") != NULL;

    install_signal_handlers();

    inotify_fd = inotify_init1(IN_NONBLOCK | IN_CLOEXEC);
    if (inotify_fd < 0)
        err(1, "kqueue");
    if (ev_trace)
        fprintf(stderr, "open_max: %d\n", 1048576);
    if (inotify_workaround)
        warnx("broken inotify workaround enabled");

    if (opt_status)
        start_status_process();

    input_interrupted = process_input(&accepted_count);
    if (input_interrupted) {
        if (terminating_signal)
            finalize_signal();
        if (status_dead)
            finalize_status_dead();
        /* Defensive fall-back; an interrupt implies one of these. */
        _exit(0);
    }

    if (accepted_count == 0)
        errx(1, "No regular files to watch");

    for (i = 0; i < records_len; i++)
        register_record_initial((int)i);

    if (terminating_signal)
        finalize_signal();

    if (!opt_noninteractive) {
        tty_fd = open("/dev/tty", O_RDONLY | O_CLOEXEC);
        if (tty_fd < 0 || tcgetattr(tty_fd, &tty_saved) != 0) {
            errx(1,
                "unable to get terminal attributes, use '-n' to run non-interactively");
        }
        tty_watch = tty_saved;
        tty_watch.c_lflag &= (tcflag_t)~(ICANON | ECHO);
        tty_is_setup = 1;
        (void)tcsetattr(tty_fd, TCSANOW, &tty_watch);
    }

    if (terminating_signal)
        finalize_signal();

    initial_pending = !opt_postpone;

    for (;;) {
        int activity;

        if (initial_pending) {
            initial_pending = 0;
            if (opt_restart) {
                (void)spawn_utility();
            } else {
                do_sync_run();
                after_sync_run();
            }
            continue;
        }

        if (child_signal_seen)
            reap_children_nonblocking();
        if (terminating_signal)
            finalize_signal();
        if (status_dead)
            finalize_status_dead();
        if (cannot_open_set)
            finalize_cannot_open();
        if (opt_restart && restart_child_exited) {
            restart_child_exited = 0;
            if (opt_exit_after)
                finalize_z_exit();
        }

        activity = poll_activity(100);
        if (activity == 0)
            continue;
        if (activity & 4)
            continue;           /* handled at the top of the loop */

        if (activity & 2) {
            int cmd = read_tty_command();
            if (cmd == 'q' || cmd == TTYCMD_EOF)
                finalize_quit();
            if (cmd == ' ') {
                if (opt_restart) {
                    terminate_restart_child();
                    if (terminating_signal)
                        finalize_signal();
                    (void)spawn_utility();
                } else {
                    do_sync_run();
                    after_sync_run();
                }
                continue;
            }
            if (!(activity & 1))
                continue;
        }

        if (activity & 1) {
            Event *events;
            int nev = 0;
            int run_needed = 0;
            int dir_altered = 0;

            events = read_and_convert_events(&nev);
            if (cannot_open_set) {
                free(events);
                finalize_cannot_open();
            }
            if (conversion_aborted) {
                free(events);
                continue;
            }
            if (nev > MAX_EVENTS)
                nev = MAX_EVENTS;
            events = collate_events(events, &nev);
            if (cannot_open_set) {
                free(events);
                finalize_cannot_open();
            }
            if (child_signal_seen)
                reap_children_nonblocking();
            if (terminating_signal) {
                free(events);
                finalize_signal();
            }
            if (status_dead) {
                free(events);
                finalize_status_dead();
            }
            if (opt_restart && restart_child_exited) {
                restart_child_exited = 0;
                if (opt_exit_after) {
                    free(events);
                    finalize_z_exit();
                }
            }
            if (conversion_aborted) {
                free(events);
                continue;
            }

            process_events(events, nev, &run_needed, &dir_altered);
            free(events);
            if (dir_altered)
                pending_dir_altered = 1;
            if (!run_needed)
                continue;

            if (opt_restart) {
                if (pending_dir_altered)
                    finalize_dir_altered();
                terminate_restart_child();
                if (terminating_signal)
                    finalize_signal();
                (void)spawn_utility();
            } else {
                do_sync_run();
                after_sync_run();
            }
        }
    }

    return 0;
}
